import { Logger } from '../../logger.js';
import { tags } from '../../parsers.js';
import { orgaIdOrNameOption } from '../global.options.js';
import { k8sIdOrNameArg } from './k8s.args.js';

export const k8sUpdateCommand = defineCommand({
  description: 'Update the settings of a Kubernetes cluster',
  since: null,
  options: {
    name: defineOption({
      name: 'name',
      schema: z.string().min(1).optional(),
      description: 'New cluster name',
      placeholder: 'name',
    }),
    description: defineOption({
      name: 'description',
      schema: z.string().max(4096).optional(),
      description: 'Free-form cluster description (empty string to clear it)',
      placeholder: 'description',
    }),
    tag: defineOption({
      name: 'tag',
      schema: z.string().transform(tags).optional(),
      description: 'Semantic tags replacing the current ones (comma-separated, empty string to clear them)',
      placeholder: 'tag[,tag...]',
    }),
    autoscaling: defineOption({
      name: 'autoscaling',
      schema: z
        .enum(['true', 'false'])
        .transform((v) => v === 'true')
        .optional(),
      description: 'Enable or disable the cluster autoscaler',
      placeholder: 'true|false',
      complete: () => ['true', 'false'],
    }),
    org: orgaIdOrNameOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    const updates = {};
    if (options.name != null) updates.name = options.name;
    if (options.description != null) updates.description = options.description;
    if (options.tag != null) updates.tags = options.tag;
    if (options.autoscaling != null) updates.features = { autoscalingEnabled: options.autoscaling };

    if (Object.keys(updates).length === 0) {
      throw new Error('Nothing to update, provide at least one of --name, --description, --tag or --autoscaling');
    }

    await k8sUpdate(options.org, clusterIdOrName, updates);

    Logger.printSuccess(
      `Cluster ${styleText('green', clusterIdOrName.addon_name || clusterIdOrName.operator_id)} successfully updated`,
    );
  },
});
